package dev.veltraph.client.core;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class OriginalDisableCleanupLifecycleTest {
 @Test void actualRegisteredDisableAllowsOnlyItsPendingAndConfirmedOldScope(){var root=new ModuleManager();var p=new Actor(root);root.register(p);p.setEnabled(true);p.original=root.lifecycleSnapshot();assertTrue(root.ownCleanupLifecycleCurrent(p.original,p));assertFalse(root.pendingOwnDisableFromMatches(p.original,p));p.setEnabled(false);assertTrue(p.sawPending);assertTrue(p.sawCleanup);assertTrue(root.ownCleanupLifecycleCurrent(p.original,p));assertFalse(root.pendingOwnDisableFromMatches(p.original,p));}
 @Test void realReenableCannotBorrowOldDisabledScope(){var root=new ModuleManager();var p=new Actor(root);root.register(p);p.setEnabled(true);p.original=root.lifecycleSnapshot();var old=p.original;p.setEnabled(false);assertTrue(root.ownCleanupLifecycleCurrent(old,p));p.setEnabled(true);assertFalse(root.ownCleanupLifecycleCurrent(old,p));}
 @Test void rawPublicOnDisableDoesNotMintPendingInvocation(){var root=new ModuleManager();var p=new Actor(root);root.register(p);p.setEnabled(true);p.original=root.lifecycleSnapshot();p.onDisable();assertFalse(p.sawPending);assertFalse(root.pendingOwnDisableFromMatches(p.original,p));}
 @Test void foreignEnableDuringDisableRevokesPendingAndConfirmedOldScope(){var root=new ModuleManager();var p=new Actor(root);var f=new Foreign();root.register(p);root.register(f);p.setEnabled(true);p.original=root.lifecycleSnapshot();p.inside=()->f.setEnabled(true);p.setEnabled(false);assertFalse(p.afterMutation);assertFalse(root.ownCleanupLifecycleCurrent(p.original,p));}
 @Test void ownEnableReentryCannotRetainOldDisableScope(){var root=new ModuleManager();var p=new Actor(root);root.register(p);p.setEnabled(true);p.original=root.lifecycleSnapshot();p.inside=()->p.setEnabled(true);p.setEnabled(false);assertFalse(p.afterMutation);assertFalse(root.ownCleanupLifecycleCurrent(p.original,p));}
 @Test void hookExceptionNeverConfirmsOldCleanupLifecycle(){var root=new ModuleManager();var p=new Actor(root);root.register(p);p.setEnabled(true);p.original=root.lifecycleSnapshot();p.hookThrows=true;assertThrows(IllegalStateException.class,()->p.setEnabled(false));assertFalse(root.ownCleanupLifecycleCurrent(p.original,p));}
 private static final class Actor extends AbstractModule {final ModuleManager root;ModuleManager.LifecycleSnapshot original;boolean sawPending,sawCleanup,afterMutation,hookThrows;Runnable inside=()->{};Actor(ModuleManager r){super("original_parent","Parent",ModuleCategory.INTERMEDIARY);root=r;}@Override public void onEnable(){}@Override public void onDisable(){sawPending=root.pendingOwnDisableFromMatches(original,this);sawCleanup=root.ownCleanupLifecycleCurrent(original,this);inside.run();afterMutation=root.pendingOwnDisableFromMatches(original,this);}@Override protected void postDisableNormalReturned(ModuleManager.OwnDisableReceipt receipt){if(hookThrows)throw new IllegalStateException("hook");}}
 private static final class Foreign extends AbstractModule {Foreign(){super("foreign","Foreign",ModuleCategory.INTERMEDIARY);}}
}
